var $bm_rt;
var freq, cycle, baseWord, dots, dots, dots, dots, dots;
freq = effect('Frequency')('Slider');
cycle = $bm_mod(Math.floor($bm_mul(time, freq)), 4);
baseWord = thisLayer._name;
dots = '';
if (cycle == 0) {
    dots = '';
} else if (cycle == 1) {
    dots = '.';
} else if (cycle == 2) {
    dots = '..';
} else {
    dots = '...';
}
$bm_rt = $bm_sum(baseWord, dots);

